properties.tools:
[
  {
    "name": "order_lookup",
    "route": "demo.order.lookup",
    "strict": true,
    "description": "An order by its id: the date it was placed, its items, the total, the currency and the order status.",
    "input_schema": {
      "type": "object",
      "properties": {
        "order_id": {
          "type": "string",
          "pattern": "^ORD-[0-9]+$"
        }
      },
      "required": [
        "order_id"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "shipment_status",
    "route": "demo.shipment.status",
    "strict": true,
    "description": "The shipment of an order: the carrier, the tracking number, the status (in_transit, delivered or lost), the date of the last update and the carrier's note.",
    "input_schema": {
      "type": "object",
      "properties": {
        "order_id": {
          "type": "string",
          "pattern": "^ORD-[0-9]+$"
        }
      },
      "required": [
        "order_id"
      ],
      "additionalProperties": false
    }
  },
  {
    "name": "issue_refund",
    "route": "demo.refund.issue",
    "write": true,
    "description": "Issue a refund to the customer of an order, once. A refund is a payment, so a supervisor approves it before it runs.",
    "input_schema": {
      "type": "object",
      "properties": {
        "order_id": {
          "type": "string",
          "pattern": "^ORD-[0-9]+$"
        },
        "amount": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "the amount to refund, at most the order's total"
        },
        "reason": {
          "type": "string",
          "minLength": 1,
          "maxLength": 200
        }
      },
      "required": [
        "order_id",
        "amount",
        "reason"
      ],
      "additionalProperties": false
    }
  }
]
